#' util_rescale
#'
#' Linearly rescale element values in a raster to a range between 0 and 1
#'
#' @param x [\code{SpatRaster}]
#'
#' @return \code{SpatRaster} with each layer independently rescaled to values
#' ranging from 0-1. Non-missing cells in constant layers are set to 0, and
#' all-\code{NA} layers remain \code{NA}.
#'
#' @details Rasters generated by \code{nlm_*} functions are scaled between 0 and 1 as default, this option can be set to \code{FALSE} if needed.
#'
#' @keywords internal
#'

util_rescale <- function(x) {
  if (!inherits(x, "SpatRaster")) {
    stop("x must be a SpatRaster.")
  }

  stats <- terra::global(x, c("min", "max"), na.rm = TRUE)
  out <- x

  for (i in seq_len(terra::nlyr(x))) {
    min_value <- stats[i, "min"]
    max_value <- stats[i, "max"]

    if (is.na(min_value) || is.na(max_value)) {
      next
    }

    if (isTRUE(all.equal(min_value, max_value))) {
      out[[i]] <- x[[i]] - min_value
    } else {
      out[[i]] <- (x[[i]] - min_value) / (max_value - min_value)
    }
  }

  names(out) <- names(x)
  out
}
